window.QBANK = window.QBANK || {};
window.QBANK["sd-pai"] = {
  level: "SD", subject: "Pendidikan Agama", duration: 900,
  questions: [
    { q: "Rukun iman berjumlah ...", options: ["4", "5", "6", "7"], answer: 2, solution: "1. Rukun artinya pokok atau dasar kepercayaan. 2. Rukun iman adalah pokok-pokok kepercayaan dalam agama Islam. 3. Jumlah rukun iman ada 6: iman kepada Allah, malaikat, kitab-kitab Allah, rasul-rasul Allah, hari akhir, serta qada dan qadar." },
    { q: "Rukun iman yang pertama adalah iman kepada ...", options: ["Allah", "malaikat", "kitab-kitab Allah", "rasul-rasul Allah"], answer: 0, solution: "1. Urutan rukun iman dimulai dari yang paling utama. 2. Rukun iman yang pertama adalah iman kepada Allah. 3. Artinya kita percaya bahwa Allah itu ada dan hanya Allah yang wajib disembah." },
    { q: "Iman kepada malaikat-malaikat Allah adalah rukun iman yang ke-...", options: ["satu", "dua", "tiga", "empat"], answer: 1, solution: "1. Urutan rukun iman: pertama iman kepada Allah, kedua iman kepada malaikat. 2. Selanjutnya: kitab-kitab Allah, rasul-rasul Allah, hari akhir, lalu qada dan qadar. 3. Jadi iman kepada malaikat adalah rukun iman yang kedua." },
    { q: "Rukun iman yang kelima adalah iman kepada ...", options: ["qada dan qadar", "malaikat", "kitab-kitab Allah", "hari akhir"], answer: 3, solution: "1. Urutan rukun iman: 1) Allah, 2) malaikat, 3) kitab-kitab Allah, 4) rasul-rasul Allah, 5) hari akhir, 6) qada dan qadar. 2. Jadi rukun iman yang kelima adalah iman kepada hari akhir. 3. Hari akhir adalah hari kiamat, saat semua manusia dibangkitkan." },
    { q: "Percaya bahwa segala sesuatu terjadi atas kehendak dan ketetapan Allah disebut iman kepada ...", options: ["hari akhir", "malaikat", "qada dan qadar", "kitab suci"], answer: 2, solution: "1. Qada artinya ketetapan Allah, sedangkan qadar artinya ukuran atau takdir. 2. Percaya bahwa semua yang terjadi sudah ditetapkan Allah disebut iman kepada qada dan qadar. 3. Ini adalah rukun iman yang keenam." },
    { q: "Rukun Islam berjumlah ...", options: ["3", "4", "6", "5"], answer: 3, solution: "1. Rukun Islam adalah pokok-pokok ajaran Islam yang wajib dikerjakan. 2. Jumlahnya ada 5: syahadat, sholat, zakat, puasa, dan haji. 3. Jadi jawaban yang benar adalah 5." },
    { q: "Rukun Islam yang pertama adalah ...", options: ["mengucapkan dua kalimat syahadat", "mendirikan sholat", "membayar zakat", "berpuasa Ramadhan"], answer: 0, solution: "1. Urutan rukun Islam dimulai dari pintu masuk agama Islam. 2. Rukun Islam yang pertama adalah mengucapkan dua kalimat syahadat. 3. Syahadat artinya bersaksi bahwa tiada Tuhan selain Allah dan Nabi Muhammad adalah utusan Allah." },
    { q: "Membayar zakat adalah rukun Islam yang ke-...", options: ["satu", "dua", "tiga", "empat"], answer: 2, solution: "1. Urutan rukun Islam: 1) syahadat, 2) sholat, 3) zakat, 4) puasa, 5) haji. 2. Jadi membayar zakat adalah rukun Islam yang ketiga. 3. Zakat adalah sebagian harta yang wajib diberikan kepada orang yang berhak." },
    { q: "Menunaikan ibadah haji ke Baitullah wajib bagi orang yang ...", options: ["sudah tua", "mampu", "sudah menikah", "tinggal di kota"], answer: 1, solution: "1. Haji adalah rukun Islam yang kelima. 2. Haji tidak wajib bagi semua orang, hanya wajib bagi yang mampu. 3. Mampu artinya sanggup biaya, sehat, dan aman dalam perjalanan." },
    { q: "Setelah membaca niat, anggota tubuh yang dibasuh pertama kali saat berwudhu adalah ...", options: ["telapak tangan", "wajah", "kepala", "kaki"], answer: 0, solution: "1. Urutan berwudhu: niat, membasuh telapak tangan, berkumur, membersihkan hidung, membasuh wajah, dan seterusnya. 2. Jadi setelah niat, yang dibasuh pertama kali adalah telapak tangan. 3. Telapak tangan dibasuh sampai pergelangan tangan." },
    { q: "Dalam urutan berwudhu, membasuh wajah dilakukan setelah ...", options: ["mengusap kepala", "membasuh kaki", "membasuh tangan sampai siku", "berkumur dan membersihkan hidung"], answer: 3, solution: "1. Urutan berwudhu: niat, membasuh telapak tangan, berkumur, membersihkan hidung, lalu membasuh wajah. 2. Jadi membasuh wajah dilakukan setelah berkumur dan membersihkan hidung. 3. Wajah dibasuh dari dahi sampai dagu." },
    { q: "Setelah membasuh wajah, gerakan wudhu berikutnya adalah membasuh ...", options: ["mengusap kepala", "kedua tangan sampai siku", "kedua kaki", "telapak tangan"], answer: 1, solution: "1. Urutan berwudhu setelah membasuh wajah adalah membasuh kedua tangan. 2. Tangan dibasuh mulai dari ujung jari sampai siku. 3. Setelah itu baru mengusap kepala." },
    { q: "Anggota tubuh yang diusap (bukan dibasuh) saat berwudhu adalah ...", options: ["wajah", "tangan", "kepala", "kaki"], answer: 2, solution: "1. Hampir semua anggota wudhu dibasuh dengan air yang mengalir. 2. Hanya kepala yang cukup diusap dengan air, tidak perlu dibasuh. 3. Jadi anggota tubuh yang diusap adalah kepala." },
    { q: "Air yang sah dipakai untuk berwudhu adalah air yang ...", options: ["berwarna", "suci dan mensucikan", "bercampur sabun", "sudah dipakai"], answer: 1, solution: "1. Syarat air untuk wudhu adalah suci dan mensucikan. 2. Contohnya air hujan, air sumur, air sungai, dan air laut. 3. Air yang sudah dipakai atau tercampur sabun tidak sah untuk wudhu." },
    { q: "Sholat wajib dikerjakan sebanyak ... dalam sehari semalam.", options: ["3 waktu", "4 waktu", "6 waktu", "5 waktu"], answer: 3, solution: "1. Sholat wajib disebut juga sholat lima waktu. 2. Lima waktu itu adalah Subuh, Dzuhur, Ashar, Maghrib, dan Isya. 3. Jadi sholat wajib dikerjakan 5 waktu dalam sehari semalam." },
    { q: "Sholat Subuh dikerjakan sebanyak ...", options: ["2 rakaat", "3 rakaat", "4 rakaat", "5 rakaat"], answer: 0, solution: "1. Setiap waktu sholat punya jumlah rakaat sendiri. 2. Sholat Subuh dikerjakan sebanyak 2 rakaat. 3. Sholat Subuh dikerjakan sebelum matahari terbit." },
    { q: "Sholat Maghrib dikerjakan sebanyak ...", options: ["2 rakaat", "4 rakaat", "3 rakaat", "1 rakaat"], answer: 2, solution: "1. Jumlah rakaat tiap sholat: Subuh 2, Dzuhur 4, Ashar 4, Maghrib 3, Isya 4. 2. Jadi sholat Maghrib dikerjakan sebanyak 3 rakaat. 3. Sholat Maghrib dikerjakan setelah matahari terbenam." },
    { q: "Jumlah seluruh rakaat sholat wajib dalam sehari semalam adalah ...", options: ["15 rakaat", "17 rakaat", "16 rakaat", "18 rakaat"], answer: 1, solution: "1. Jumlah rakaat: Subuh 2, Dzuhur 4, Ashar 4, Maghrib 3, Isya 4. 2. Kalau dijumlahkan: $2+4+4+3+4=17$. 3. Jadi seluruh rakaat sholat wajib dalam sehari semalam ada 17 rakaat." },
    { q: "Salah satu syarat sah sholat adalah ...", options: ["menghadap kiblat", "berbicara", "tertawa", "berlari"], answer: 0, solution: "1. Syarat sah sholat adalah hal yang harus dipenuhi sebelum sholat. 2. Salah satunya adalah menghadap kiblat, yaitu Ka'bah di Mekah. 3. Berbicara, tertawa, dan berlari justru membatalkan sholat." },
    { q: "Rukun sholat yang pertama adalah ...", options: ["takbiratul ihram", "rukuk", "sujud", "niat"], answer: 3, solution: "1. Rukun sholat adalah gerakan dan bacaan yang wajib ada dalam sholat. 2. Rukun sholat yang pertama adalah niat, yaitu menyengaja sholat dalam hati. 3. Setelah niat baru takbiratul ihram." },
    { q: "Bacaan yang wajib dibaca pada setiap rakaat sholat adalah ...", options: ["surat Al-Ikhlas", "doa qunut", "surat Al-Fatihah", "tahiyat akhir"], answer: 2, solution: "1. Dalam setiap rakaat sholat ada bacaan yang tidak boleh ditinggalkan. 2. Bacaan itu adalah surat Al-Fatihah. 3. Sholat tidak sah kalau Al-Fatihah tidak dibaca." },
    { q: "Jumlah nabi dan rasul yang wajib kita ketahui ada ...", options: ["20", "25", "30", "40"], answer: 1, solution: "1. Jumlah nabi dan rasul sebenarnya sangat banyak. 2. Namun yang wajib kita ketahui dan hafal namanya ada 25. 3. Mulai dari Nabi Adam sampai Nabi Muhammad." },
    { q: "Nabi yang pertama adalah Nabi ...", options: ["Adam", "Nuh", "Ibrahim", "Musa"], answer: 0, solution: "1. Nabi pertama adalah manusia pertama yang diciptakan Allah. 2. Allah menciptakan Nabi Adam dari tanah. 3. Jadi nabi yang pertama adalah Nabi Adam." },
    { q: "Nabi terakhir yang menjadi penutup para nabi adalah Nabi ...", options: ["Isa", "Musa", "Muhammad", "Ibrahim"], answer: 2, solution: "1. Setelah Nabi Muhammad tidak ada lagi nabi. 2. Karena itu beliau disebut penutup para nabi (khatamun nabiyyin). 3. Jadi nabi terakhir adalah Nabi Muhammad." },
    { q: "Nabi yang termasuk Ulul Azmi karena ketabahan luar biasa dalam berdakwah adalah Nabi ...", options: ["Yusuf", "Daud", "Yunus", "Nuh"], answer: 3, solution: "1. Ulul Azmi adalah gelar untuk 5 nabi yang sangat tabah: Nuh, Ibrahim, Musa, Isa, dan Muhammad. 2. Nabi Nuh berdakwah selama 950 tahun dengan penuh kesabaran. 3. Jadi salah satu nabi Ulul Azmi adalah Nabi Nuh." },
    { q: "Nabi yang dibakar Raja Namrud tetapi selamat karena api menjadi dingin atas izin Allah adalah Nabi ...", options: ["Ismail", "Ibrahim", "Ishaq", "Yakub"], answer: 1, solution: "1. Nabi Ibrahim mengajak Raja Namrud menyembah Allah, lalu ia ditangkap. 2. Raja Namrud memerintahkan agar Nabi Ibrahim dibakar hidup-hidup. 3. Atas izin Allah api menjadi dingin sehingga Nabi Ibrahim selamat." },
    { q: "Nabi yang membelah Laut Merah dengan tongkatnya atas izin Allah adalah Nabi ...", options: ["Musa", "Harun", "Isa", "Ilyas"], answer: 0, solution: "1. Nabi Musa dan pengikutnya dikejar Fir'aun sampai ke tepi Laut Merah. 2. Atas perintah Allah, Nabi Musa memukulkan tongkatnya ke laut. 3. Laut pun terbelah sehingga mereka bisa lewat dengan selamat." },
    { q: "Nabi yang ditelan ikan besar lalu berdoa di dalam perut ikan adalah Nabi ...", options: ["Ayyub", "Zakaria", "Yunus", "Yahya"], answer: 2, solution: "1. Nabi Yunus meninggalkan kaumnya lalu naik kapal dan terlempar ke laut. 2. Atas izin Allah, seekor ikan besar menelan Nabi Yunus. 3. Di dalam perut ikan beliau terus berdoa sampai akhirnya dikeluarkan dengan selamat." },
    { q: "Nabi yang membangun Ka'bah bersama putranya, Nabi Ismail, adalah Nabi ...", options: ["Ishaq", "Ibrahim", "Yakub", "Luth"], answer: 1, solution: "1. Allah memerintahkan Nabi Ibrahim membangun rumah suci pertama. 2. Nabi Ibrahim mengerjakannya bersama putranya, Nabi Ismail. 3. Bangunan itu adalah Ka'bah yang ada di kota Mekah." },
    { q: "Kitab suci yang diterima Nabi Musa adalah kitab ...", options: ["Zabur", "Injil", "Al-Qur'an", "Taurat"], answer: 3, solution: "1. Setiap rasul menerima kitab suci dari Allah. 2. Nabi Daud menerima Zabur, Nabi Isa menerima Injil, Nabi Muhammad menerima Al-Qur'an. 3. Nabi Musa menerima kitab Taurat di Gunung Tursina." },
    { q: "Berkata benar dan tidak berbohong disebut akhlak ...", options: ["jujur", "sombong", "malas", "kikir"], answer: 0, solution: "1. Akhlak terpuji adalah perilaku baik yang disukai Allah. 2. Berkata benar apa adanya dan tidak berbohong disebut jujur. 3. Orang jujur dipercaya dan disayang banyak orang." },
    { q: "Contoh akhlak terpuji kepada orang tua adalah ...", options: ["membentak mereka", "tidak mendengarkan nasihat", "meminta uang terus", "membantu dan menghormati mereka"], answer: 3, solution: "1. Allah memerintahkan kita berbakti kepada orang tua. 2. Membentak dan tidak mendengarkan nasihat termasuk durhaka. 3. Jadi contoh akhlak terpuji adalah membantu dan menghormati orang tua." },
    { q: "Datang ke sekolah tepat waktu dan mengerjakan tugas dengan tertib adalah contoh sikap ...", options: ["malas", "ceroboh", "disiplin", "manja"], answer: 2, solution: "1. Disiplin artinya taat aturan dan tepat waktu. 2. Datang tepat waktu dan tertib mengerjakan tugas adalah sikap disiplin. 3. Anak disiplin disenangi guru dan berprestasi." },
    { q: "Menolong teman yang sedang kesulitan adalah contoh akhlak ...", options: ["tercela", "terpuji", "sombong", "dengki"], answer: 1, solution: "1. Akhlak terbagi dua: terpuji (baik) dan tercela (buruk). 2. Menolong teman yang kesulitan adalah perbuatan baik. 3. Jadi menolong teman termasuk akhlak terpuji." },
    { q: "Lawan dari akhlak terpuji adalah akhlak ...", options: ["tercela", "mulia", "baik", "sopan"], answer: 0, solution: "1. Akhlak terpuji artinya perilaku yang baik dan mulia. 2. Lawannya adalah perilaku buruk yang dibenci Allah. 3. Perilaku buruk itu disebut akhlak tercela, contohnya berbohong dan sombong." },
    { q: "Doa yang dibaca sebelum makan adalah ...", options: ["Bismika Allahumma ahya wa amut", "Allahumma inni a'udzu bika minal khubutsi wal khabaits", "Allahumma barik lana fima razaqtana wa qina 'adzabannar", "Ghufranaka"], answer: 2, solution: "1. Doa sebelum makan: Allahumma barik lana fima razaqtana wa qina 'adzabannar. 2. Artinya: Ya Allah, berkahilah rezeki kami dan jauhkan kami dari siksa neraka. 3. Pilihan lain adalah doa sebelum tidur, doa masuk WC, dan doa keluar WC." },
    { q: "Doa yang dibaca sebelum tidur adalah ...", options: ["Allahumma barik lana fima razaqtana", "Bismika Allahumma ahya wa bismika amut", "Ghufranaka", "Allahummaghfirli waliwalidayya"], answer: 1, solution: "1. Doa sebelum tidur: Bismika Allahumma ahya wa bismika amut. 2. Artinya: Dengan nama-Mu ya Allah aku hidup dan aku mati. 3. Doa ini dibaca agar tidur kita dijaga Allah." },
    { q: "Saat masuk ke WC atau kamar mandi, kaki yang didahulukan adalah kaki ...", options: ["kanan", "keduanya", "melompat", "kiri"], answer: 3, solution: "1. Ada adab saat masuk WC: mendahulukan kaki kiri. 2. Sebelum masuk juga membaca doa minta perlindungan dari setan. 3. Saat keluar WC barulah mendahulukan kaki kanan." },
    { q: "Doa untuk kedua orang tua berbunyi ...", options: ["Allahummaghfirli waliwalidayya warhamhuma kama rabbayani shaghira", "Bismika Allahumma ahya wa amut", "Allahumma barik lana fima razaqtana", "Ghufranaka"], answer: 0, solution: "1. Doa untuk orang tua: Allahummaghfirli waliwalidayya warhamhuma kama rabbayani shaghira. 2. Artinya: Ya Allah, ampunilah aku dan kedua orang tuaku, sayangilah mereka seperti mereka menyayangiku waktu kecil. 3. Doa ini dibaca agar orang tua disayangi Allah." },
    { q: "Puasa wajib dikerjakan pada bulan ...", options: ["Syawal", "Ramadhan", "Syakban", "Muharram"], answer: 1, solution: "1. Puasa Ramadhan adalah rukun Islam yang keempat. 2. Puasa wajib dikerjakan selama satu bulan penuh pada bulan Ramadhan. 3. Saat puasa kita menahan lapar, haus, dan hawa nafsu dari fajar sampai maghrib." },
    { q: "Salah satu hal yang membatalkan puasa adalah ...", options: ["tidur siang", "berkumur saat wudhu", "makan dan minum dengan sengaja", "bermain"], answer: 2, solution: "1. Puasa batal kalau melakukan hal yang dilarang dengan sengaja. 2. Makan dan minum dengan sengaja jelas membatalkan puasa. 3. Tidur siang, berkumur saat wudhu, dan bermain tidak membatalkan puasa." },
    { q: "Malam yang lebih baik dari seribu bulan dan terdapat di bulan Ramadhan disebut malam ...", options: ["Lailatul Qadar", "Nisfu Syakban", "Idul Fitri", "Idul Adha"], answer: 0, solution: "1. Di bulan Ramadhan ada satu malam yang sangat istimewa. 2. Malam itu lebih baik dari seribu bulan, namanya malam Lailatul Qadar. 3. Malam Lailatul Qadar ada pada sepuluh malam terakhir bulan Ramadhan." },
    { q: "Jumlah Asmaul Husna ada ...", options: ["50", "100", "25", "99"], answer: 3, solution: "1. Asmaul Husna artinya nama-nama Allah yang baik. 2. Jumlah Asmaul Husna ada 99 nama. 3. Contohnya Ar-Rahman, Ar-Rahim, dan Al-Malik." },
    { q: "Asmaul Husna Ar-Rahman artinya Allah Maha ...", options: ["Penyayang", "Pencipta", "Pengasih", "Mengetahui"], answer: 2, solution: "1. Ar-Rahman adalah salah satu Asmaul Husna. 2. Ar-Rahman artinya Allah Maha Pengasih. 3. Kasih sayang Allah meliputi semua makhluk-Nya." },
    { q: "Asmaul Husna Al-Khaliq artinya Allah Maha ...", options: ["Pengampun", "Pencipta", "Mendengar", "Melihat"], answer: 1, solution: "1. Al-Khaliq adalah salah satu Asmaul Husna. 2. Al-Khaliq artinya Allah Maha Pencipta. 3. Allah menciptakan langit, bumi, dan seluruh isinya." },
    { q: "Asmaul Husna yang artinya Maha Pemberi Rezeki adalah ...", options: ["Ar-Razzaq", "Al-Ghafur", "As-Sami'", "Al-Bashir"], answer: 0, solution: "1. Setiap Asmaul Husna punya arti sendiri. 2. Ar-Razzaq artinya Allah Maha Pemberi Rezeki. 3. Al-Ghafur artinya Maha Pengampun, As-Sami' artinya Maha Mendengar." },
    { q: "Surat pertama dalam Al-Qur'an yang wajib dibaca di setiap rakaat sholat adalah surat ...", options: ["Al-Ikhlas", "An-Nas", "Al-Falaq", "Al-Fatihah"], answer: 3, solution: "1. Surat pertama dalam Al-Qur'an adalah surat Al-Fatihah. 2. Surat Al-Fatihah wajib dibaca pada setiap rakaat sholat. 3. Al-Fatihah disebut juga Ummul Kitab, artinya induk Al-Qur'an." },
    { q: "Surat Al-Fatihah terdiri dari ... ayat.", options: ["5 ayat", "6 ayat", "7 ayat", "8 ayat"], answer: 2, solution: "1. Surat Al-Fatihah adalah surat pembuka Al-Qur'an. 2. Surat Al-Fatihah terdiri dari 7 ayat. 3. Ayat pertamanya berbunyi Bismillahirrahmanirrahim." },
    { q: "Surat yang menjelaskan tentang keesaan Allah dan terdiri dari 4 ayat adalah surat ...", options: ["Al-Kautsar", "Al-Ikhlas", "An-Nashr", "Al-'Ashr"], answer: 1, solution: "1. Surat Al-Ikhlas menjelaskan bahwa Allah itu Esa (satu). 2. Surat Al-Ikhlas terdiri dari 4 ayat. 3. Al-Kautsar, An-Nashr, dan Al-'Ashr masing-masing terdiri dari 3 ayat." },
    { q: "Surat terakhir dalam Al-Qur'an adalah surat ...", options: ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Lahab"], answer: 0, solution: "1. Al-Qur'an ditutup dengan surat An-Nas. 2. Jadi surat terakhir dalam Al-Qur'an adalah surat An-Nas. 3. Surat An-Nas berisi permohonan perlindungan dari godaan setan." },
{ q: "Niat berwudhu dibaca dalam hati pada saat...", options: ["membasuh wajah", "selesai berwudhu", "sebelum tidur", "hendak makan"], answer: 0, solution: "1. Niat wudhu dibaca dalam hati, bukan diucapkan keras. 2. Waktunya berbarengan dengan basuhan wajah yang pertama. 3. Tanpa niat, wudhu menjadi tidak sah." },
{ q: "Membaca basmalah sebelum berwudhu hukumnya...", options: ["wajib", "haram", "sunnah", "makruh"], answer: 2, solution: "1. Basmalah artinya menyebut nama Allah. 2. Membacanya di awal wudhu hukumnya sunnah. 3. Wudhu tetap sah meski lupa membacanya." },
{ q: "Bersiwak sebelum berwudhu artinya...", options: ["mencuci tangan", "membasuh kaki", "membersihkan gigi", "mengusap kepala"], answer: 2, solution: "1. Siwak berarti membersihkan gigi dan mulut. 2. Bisa memakai kayu siwak atau sikat gigi. 3. Ini sunnah agar mulut bersih saat beribadah." },
{ q: "Ketika berwudhu, sunnah mendahulukan anggota badan yang...", options: ["kiri", "kanan", "tengah", "belakang"], answer: 1, solution: "1. Sunnah mendahulukan anggota yang kanan. 2. Misalnya tangan kanan dibasuh sebelum tangan kiri. 3. Ini mengikuti kebiasaan Rasulullah." },
{ q: "Setiap anggota wudhu sunnah dibasuh sebanyak...", options: ["satu kali", "tiga kali", "dua kali", "lima kali"], answer: 1, solution: "1. Membasuh tiga kali itu sunnah. 2. Sekali basuhan sebenarnya sudah sah. 3. Tiga kali membuat wudhu lebih sempurna." },
{ q: "Setelah selesai berwudhu, disunnahkan membaca...", options: ["doa makan", "doa sebelum tidur", "doa setelah wudhu", "doa masuk WC"], answer: 2, solution: "1. Ada doa khusus setelah wudhu. 2. Diawali dengan dua kalimat syahadat. 3. Jangan lupa membacanya setiap selesai wudhu." },
{ q: "Salah satu keutamaan membaca doa setelah wudhu adalah...", options: ["menjadi kaya raya", "dibukakan pintu-pintu surga", "tidak pernah sakit", "panjang umur"], answer: 1, solution: "1. Doa setelah wudhu memiliki keutamaan besar. 2. Salah satunya dibukakan pintu-pintu surga. 3. Maka biasakan membacanya." },
{ q: "Berikut ini yang membatalkan wudhu adalah...", options: ["bersin", "kentut", "batuk", "tersenyum"], answer: 1, solution: "1. Kentut adalah keluarnya gas dari dubur. 2. Kentut membatalkan wudhu. 3. Bersin, batuk, dan tersenyum tidak membatalkan." },
{ q: "Buang air kecil atau buang air besar menyebabkan...", options: ["wudhu batal", "wudhu tetap sah", "puasa ikut batal", "tidak perlu wudhu lagi"], answer: 0, solution: "1. Buang air kecil atau besar membatalkan wudhu. 2. Sebelum wudhu lagi harus istinja dulu. 3. Setelah itu barulah berwudhu kembali." },
{ q: "Tidur nyenyak sambil berbaring membatalkan wudhu karena orang tidur...", options: ["bermimpi buruk", "badannya lelah", "tidak sadar jika kentut", "berkeringat"], answer: 2, solution: "1. Orang yang tidur nyenyak tidak sadar. 2. Ia bisa kentut tanpa terasa. 3. Maka wudhunya batal dan harus diulang." },
{ q: "Menyentuh kemaluan dengan telapak tangan...", options: ["tidak membatalkan", "disunnahkan", "diwajibkan", "membatalkan wudhu"], answer: 3, solution: "1. Menyentuh kemaluan membatalkan wudhu. 2. Berlaku untuk kemaluan sendiri. 3. Harus berwudhu lagi sebelum sholat." },
{ q: "Orang yang murtad, yaitu keluar dari Islam, maka wudhunya...", options: ["batal", "tetap sah", "menjadi sunnah", "menjadi wajib"], answer: 0, solution: "1. Murtad artinya keluar dari agama Islam. 2. Murtad membatalkan wudhu. 3. Ia wajib kembali masuk Islam lalu berwudhu lagi." },
{ q: "Tayamum boleh dilakukan apabila...", options: ["tidak menemukan air", "malas berwudhu", "airnya terasa dingin", "sedang terburu-buru"], answer: 0, solution: "1. Tayamum adalah bersuci pengganti wudhu. 2. Boleh dilakukan jika tidak ada air. 3. Tidak boleh hanya karena malas." },
{ q: "Orang yang sakit dan dilarang dokter terkena air, ia boleh...", options: ["meninggalkan sholat", "sholat tanpa bersuci", "menunda sholat selamanya", "bertayamum"], answer: 3, solution: "1. Orang sakit yang bahaya kena air boleh tayamum. 2. Tayamum sah sebagai pengganti wudhu. 3. Sholat tetap wajib dikerjakan." },
{ q: "Cara bertayamum yang benar adalah...", options: ["niat lalu mengusap wajah dan kedua tangan dengan debu suci", "membasuh kaki dengan debu", "mandi dengan debu", "meniup debu ke badan"], answer: 0, solution: "1. Tayamum diawali niat dalam hati. 2. Kemudian usap wajah dengan debu suci. 3. Lalu usap kedua tangan sampai siku." },
{ q: "Debu yang dipakai untuk tayamum harus...", options: ["kotor", "basah", "suci", "bercampur najis"], answer: 2, solution: "1. Debu tayamum harus suci dan bersih. 2. Debu yang bernajis tidak sah dipakai. 3. Contohnya debu tanah yang bersih." },
{ q: "Mandi wajib dilakukan untuk menghilangkan...", options: ["hadats kecil", "hadats besar", "najis ringan", "keringat badan"], answer: 1, solution: "1. Hadats besar dihilangkan dengan mandi wajib. 2. Contohnya setelah haid atau junub. 3. Hadats kecil cukup dihilangkan dengan wudhu." },
{ q: "Ketika mandi wajib, seluruh tubuh harus...", options: ["terkena air", "digosok sabun", "direndam air lama", "dikeringkan dulu"], answer: 0, solution: "1. Syarat mandi wajib adalah air merata. 2. Seluruh tubuh termasuk rambut harus basah. 3. Sabun hanya pelengkap, bukan syarat." },
{ q: "Niat mandi wajib dibaca...", options: ["di akhir mandi", "di awal mandi", "setelah makan", "sebelum tidur"], answer: 1, solution: "1. Niat mandi wajib dibaca dalam hati. 2. Waktunya di awal mulai mandi. 3. Tanpa niat, mandinya tidak sah." },
{ q: "Air kencing bayi laki-laki yang belum makan apa-apa termasuk najis...", options: ["mukhaffafah", "mutawassithah", "mughallazhah", "bukan najis"], answer: 0, solution: "1. Najis ada tiga macam. 2. Kencing bayi laki-laki yang belum makan termasuk mukhaffafah. 3. Mukhaffafah artinya najis ringan." },
{ q: "Cara mensucikan najis mukhaffafah adalah...", options: ["dibasuh tujuh kali", "diperciki air", "dicuci dengan tanah", "dibakar"], answer: 1, solution: "1. Najis mukhaffafah itu najis ringan. 2. Cukup diperciki atau disiram air. 3. Tidak perlu dicuci berkali-kali." },
{ q: "Contoh najis mutawassithah adalah...", options: ["air liur anjing", "kotoran manusia", "air kencing bayi", "debu bersih"], answer: 1, solution: "1. Mutawassithah artinya najis sedang. 2. Contohnya kotoran, darah, dan muntah. 3. Air liur anjing termasuk najis berat." },
{ q: "Cara mensucikan najis mutawassithah adalah...", options: ["diperciki air saja", "dibiarkan kering", "dibasuh sampai hilang wujudnya", "dijemur saja"], answer: 2, solution: "1. Najis sedang harus dibasuh dengan air. 2. Basuh sampai hilang warna, bau, dan rasanya. 3. Biasanya cukup tiga kali basuhan." },
{ q: "Cara mensucikan najis mughallazhah adalah...", options: ["dibasuh tujuh kali dan salah satunya dengan tanah", "diperciki air", "dibasuh sekali saja", "dijemur di bawah matahari"], answer: 0, solution: "1. Najis mughallazhah contohnya jilatan anjing. 2. Dicuci tujuh kali dengan air. 3. Salah satu basuhan dicampur tanah." },
{ q: "Istinja adalah...", options: ["berwudhu sebelum sholat", "mandi sebelum tidur", "mencuci pakaian", "membersihkan diri setelah buang air"], answer: 3, solution: "1. Istinja artinya bersuci setelah buang air. 2. Dilakukan setelah buang air kecil atau besar. 3. Hukumnya wajib." },
{ q: "Membersihkan najis setelah buang air paling utama menggunakan...", options: ["tisu", "batu", "air", "daun"], answer: 2, solution: "1. Istinja paling utama memakai air. 2. Air membersihkan lebih sempurna. 3. Boleh juga dengan batu jika tidak ada air." },
{ q: "Istinja dengan batu dilakukan sebanyak...", options: ["satu kali", "dua kali", "tiga kali atau ganjil", "sepuluh kali"], answer: 2, solution: "1. Jika tidak ada air boleh pakai batu. 2. Usap sebanyak tiga kali atau bilangan ganjil. 3. Batu yang dipakai harus suci." },
{ q: "Salah satu adab buang air adalah tidak...", options: ["membaca doa", "menghadap atau membelakangi kiblat", "menutup aurat", "beristinja"], answer: 1, solution: "1. Saat buang air ada adabnya. 2. Dilarang menghadap atau membelakangi kiblat. 3. Ini bentuk penghormatan pada kiblat." },
{ q: "Syarat wajib sholat yang pertama adalah beragama...", options: ["Islam", "Kristen", "Hindu", "Buddha"], answer: 0, solution: "1. Sholat hanya wajib bagi muslim. 2. Orang nonmuslim tidak wajib sholat. 3. Masuk Islam dulu baru wajib sholat." },
{ q: "Anak kecil belum wajib sholat karena belum...", options: ["pintar", "kuat", "tinggi", "baligh"], answer: 3, solution: "1. Baligh artinya sudah dewasa. 2. Anak yang belum baligh belum wajib sholat. 3. Tapi anak dilatih sholat sejak kecil." },
{ q: "Orang gila tidak wajib sholat karena tidak...", options: ["berakal", "kaya", "sehat", "pintar"], answer: 0, solution: "1. Syarat wajib sholat adalah berakal sehat. 2. Orang gila tidak berakal. 3. Maka ia tidak wajib sholat." },
{ q: "Sebelum sholat, badan harus suci dari...", options: ["hadats dan najis", "keringat", "debu", "bau badan"], answer: 0, solution: "1. Syarat sah sholat adalah suci. 2. Suci dari hadats dengan wudhu. 3. Suci dari najis pada badan." },
{ q: "Pakaian yang terkena najis dipakai untuk sholat, maka sholatnya...", options: ["tetap sah", "makruh", "tidak sah", "sunnah"], answer: 2, solution: "1. Pakaian sholat harus suci dari najis. 2. Jika terkena najis, sholat tidak sah. 3. Ganti atau sucikan dulu pakaiannya." },
{ q: "Saat sholat kita wajib menghadap ke...", options: ["kiblat", "timur", "barat", "matahari"], answer: 0, solution: "1. Kiblat umat Islam adalah Ka'bah. 2. Sholat wajib menghadap kiblat. 3. Di Indonesia kiblat mengarah ke barat laut." },
{ q: "Sholat Dzuhur dikerjakan setelah...", options: ["matahari terbit", "matahari tergelincir", "tengah malam", "maghrib"], answer: 1, solution: "1. Setiap sholat punya waktunya. 2. Dzuhur dimulai saat matahari tergelincir. 3. Sholat sebelum masuk waktu tidak sah." },
{ q: "Menutup aurat saat sholat hukumnya...", options: ["syarat sah", "sunnah", "makruh", "tidak perlu"], answer: 0, solution: "1. Menutup aurat syarat sah sholat. 2. Aurat laki-laki antara pusar dan lutut. 3. Jika aurat terbuka, sholat tidak sah." },
{ q: "Takbiratul ihram adalah...", options: ["takbir saat ruku", "takbir saat sujud", "takbir hari raya", "takbir pertama memulai sholat"], answer: 3, solution: "1. Takbiratul ihram dibaca di awal sholat. 2. Lafaznya Allahu akbar. 3. Setelah itu tidak boleh bicara atau makan." },
{ q: "Rukun sholat yang dilakukan setelah berdiri dan membaca Al-Fatihah adalah...", options: ["ruku", "sujud", "duduk", "salam"], answer: 0, solution: "1. Urutan sholat harus tertib. 2. Setelah berdiri lalu ruku. 3. Ruku dengan membungkuk dan tangan di lutut." },
{ q: "I'tidal adalah gerakan...", options: ["bangkit dari ruku", "turun untuk sujud", "duduk di antara sujud", "menoleh saat salam"], answer: 0, solution: "1. I'tidal artinya berdiri tegak. 2. Dilakukan setelah bangkit dari ruku. 3. Sambil membaca sami'allahu liman hamidah." },
{ q: "Setelah sujud pertama, rukun berikutnya adalah...", options: ["langsung berdiri", "ruku lagi", "duduk di antara dua sujud", "salam"], answer: 2, solution: "1. Setiap rakaat ada dua kali sujud. 2. Di antara keduanya ada duduk. 3. Duduk ini termasuk rukun sholat." },
{ q: "Tasyahud akhir dibaca pada...", options: ["rakaat pertama", "rakaat terakhir", "setiap rakaat", "sebelum takbir"], answer: 1, solution: "1. Tasyahud akhir dibaca di rakaat terakhir. 2. Dilakukan sambil duduk. 3. Setelah itu diakhiri dengan salam." },
{ q: "Rukun sholat yang terakhir adalah...", options: ["salam", "sujud", "ruku", "tasyahud"], answer: 0, solution: "1. Sholat diakhiri dengan salam. 2. Menoleh ke kanan lalu ke kiri. 3. Setelah salam boleh bicara lagi." },
{ q: "Mengerjakan rukun sholat harus berurutan, ini disebut...", options: ["tertib", "khusyuk", "tuma'ninah", "niat"], answer: 0, solution: "1. Tertib artinya berurutan. 2. Tidak boleh sujud sebelum ruku. 3. Tertib termasuk rukun sholat." },
{ q: "Doa iftitah dibaca...", options: ["setelah takbiratul ihram", "sebelum takbir", "saat ruku", "saat sujud"], answer: 0, solution: "1. Doa iftitah dibaca setelah takbiratul ihram. 2. Sebelum membaca Al-Fatihah. 3. Hukumnya sunnah." },
{ q: "Membaca ta'awudz sebelum Al-Fatihah hukumnya...", options: ["wajib", "sunnah", "haram", "makruh"], answer: 1, solution: "1. Ta'awudz artinya berlindung pada Allah. 2. Dibaca sebelum Al-Fatihah. 3. Hukumnya sunnah." },
{ q: "Setelah imam membaca Al-Fatihah, makmum disunnahkan membaca...", options: ["subhanallah", "alhamdulillah", "amin", "allahu akbar"], answer: 2, solution: "1. Amin artinya kabulkanlah. 2. Dibaca setelah Al-Fatihah selesai. 3. Makmum ikut membaca amin bersama imam." },
{ q: "Doa qunut biasanya dibaca pada sholat...", options: ["Subuh", "Dzuhur", "Maghrib", "Isya"], answer: 0, solution: "1. Qunut adalah doa khusus. 2. Dibaca saat i'tidal rakaat kedua sholat Subuh. 3. Hukumnya sunnah." },
{ q: "Berbicara dengan sengaja saat sholat menyebabkan sholat...", options: ["batal", "tetap sah", "makruh", "sunnah"], answer: 0, solution: "1. Saat sholat tidak boleh bicara. 2. Bicara sengaja membatalkan sholat. 3. Harus mengulang sholat dari awal." },
{ q: "Makan atau minum saat sholat hukumnya...", options: ["tidak membatalkan", "disunnahkan", "dimakruhkan", "membatalkan sholat"], answer: 3, solution: "1. Makan dan minum membatalkan sholat. 2. Walau hanya sedikit. 3. Selesaikan makan dulu baru sholat." },
{ q: "Bergerak banyak dan berturut-turut saat sholat...", options: ["membatalkan sholat", "tidak membatalkan", "disunnahkan", "wajib"], answer: 0, solution: "1. Gerakan banyak membatalkan sholat. 2. Contohnya berjalan atau melompat. 3. Gerakan sedikit seperti menggaruk tidak batal." },
{ q: "Aurat terbuka saat sholat menyebabkan...", options: ["sholat tetap sah", "sholat batal", "pahala berkurang", "tidak apa-apa"], answer: 1, solution: "1. Menutup aurat syarat sah sholat. 2. Jika aurat terbuka, sholat batal. 3. Perbaiki pakaian lalu ulangi sholat." },
{ q: "Pakaian terkena najis saat sholat, maka...", options: ["sholatnya batal", "sholatnya sah", "lanjutkan saja", "tidak masalah"], answer: 0, solution: "1. Suci dari najis syarat sah sholat. 2. Terkena najis membatalkan sholat. 3. Sucikan dulu lalu sholat lagi." },
{ q: "Menengok ke kanan dan ke kiri saat sholat hukumnya...", options: ["makruh", "wajib", "sunnah", "haram"], answer: 0, solution: "1. Makruh artinya sebaiknya ditinggalkan. 2. Menengok saat sholat itu makruh. 3. Pandangan fokus ke tempat sujud." },
{ q: "Bermain-main dengan pakaian saat sholat hukumnya...", options: ["wajib", "sunnah", "makruh", "membatalkan"], answer: 2, solution: "1. Bermain pakaian mengganggu khusyuk. 2. Hukumnya makruh. 3. Fokuslah pada bacaan sholat." },
{ q: "Sholat sambil menahan buang air hukumnya...", options: ["makruh", "wajib", "sunnah", "haram"], answer: 0, solution: "1. Menahan buang air mengganggu khusyuk. 2. Sholat dalam keadaan itu makruh. 3. Sebaiknya buang air dulu baru sholat." },
{ q: "Bacaan ruku adalah...", options: ["subhana rabbiyal azhim", "subhana rabbiyal a'la", "sami'allahu liman hamidah", "rabbighfirli"], answer: 0, solution: "1. Ruku dibaca subhana rabbiyal azhim. 2. Artinya Mahasuci Tuhanku Yang Mahaagung. 3. Dibaca tiga kali." },
{ q: "Saat i'tidal kita membaca...", options: ["allahu akbar", "sami'allahu liman hamidah", "subhanallah", "alhamdulillah"], answer: 1, solution: "1. I'tidal dibaca sami'allahu liman hamidah. 2. Artinya Allah mendengar yang memuji-Nya. 3. Lalu dilanjut rabbana lakal hamdu." },
{ q: "Bacaan sujud adalah...", options: ["subhana rabbiyal azhim", "sami'allahu liman hamidah", "rabbighfirli", "subhana rabbiyal a'la"], answer: 3, solution: "1. Sujud dibaca subhana rabbiyal a'la. 2. Artinya Mahasuci Tuhanku Yang Mahatinggi. 3. Dibaca tiga kali." },
{ q: "Duduk di antara dua sujud membaca...", options: ["rabbighfirli warhamni", "subhanallah", "allahu akbar", "al-fatihah"], answer: 0, solution: "1. Duduk di antara dua sujud ada bacaannya. 2. Diawali rabbighfirli warhamni. 3. Artinya memohon ampun dan rahmat." },
{ q: "Tasyahud awal dibaca pada...", options: ["rakaat kedua sholat yang lebih dari dua rakaat", "rakaat pertama", "rakaat terakhir", "setiap rakaat"], answer: 0, solution: "1. Tasyahud awal hanya ada di sholat 3-4 rakaat. 2. Dibaca setelah sujud rakaat kedua. 3. Hukumnya sunnah." },
{ q: "Pada tasyahud akhir kita membaca...", options: ["doa iftitah", "ayat kursi", "sholawat kepada Nabi", "surat pendek"], answer: 2, solution: "1. Tasyahud akhir berisi sholawat. 2. Sholawat untuk Nabi Muhammad. 3. Lalu diakhiri dengan salam." },
{ q: "Salam untuk mengakhiri sholat dibaca sambil...", options: ["menoleh ke kanan lalu ke kiri", "menunduk", "mengangkat tangan", "berdiri"], answer: 0, solution: "1. Salam dibaca assalamu'alaikum warahmatullah. 2. Menoleh ke kanan dulu. 3. Lalu menoleh ke kiri." },
{ q: "Niat sholat Subuh berbunyi usholli fardhash shubhi...", options: ["rak'ataini", "arba'a raka'atin", "tsalatsa raka'atin", "khamsa raka'atin"], answer: 0, solution: "1. Sholat Subuh jumlahnya dua rakaat. 2. Dua rakaat bahasa Arabnya rak'ataini. 3. Niat dibaca dalam hati." },
{ q: "Niat sholat Dzuhur adalah usholli fardhazh zhuhri...", options: ["rak'ataini", "tsalatsa raka'atin", "khamsa raka'atin", "arba'a raka'atin"], answer: 3, solution: "1. Sholat Dzuhur empat rakaat. 2. Empat bahasa Arabnya arba'a. 3. Ditambah mustaqbilal qiblati." },
{ q: "Sholat Ashar dikerjakan sebanyak...", options: ["dua rakaat", "tiga rakaat", "empat rakaat", "lima rakaat"], answer: 2, solution: "1. Sholat Ashar empat rakaat. 2. Niatnya usholli fardhal ashri arba'a raka'atin. 3. Dikerjakan setelah Dzuhur." },
{ q: "Niat sholat Maghrib menyebut jumlah...", options: ["tiga rakaat", "dua rakaat", "empat rakaat", "satu rakaat"], answer: 0, solution: "1. Sholat Maghrib tiga rakaat. 2. Tiga bahasa Arabnya tsalatsa. 3. Ini sholat fardhu yang ganjil." },
{ q: "Usholli fardhal isya'i arba'a raka'atin adalah niat sholat...", options: ["Subuh", "Isya", "Maghrib", "Jumat"], answer: 1, solution: "1. Isya artinya malam. 2. Sholat Isya empat rakaat. 3. Dikerjakan setelah Maghrib." },
{ q: "Hukum sholat Jumat bagi laki-laki muslim yang dewasa adalah...", options: ["wajib", "sunnah", "makruh", "haram"], answer: 0, solution: "1. Sholat Jumat wajib bagi laki-laki. 2. Dikerjakan setiap hari Jumat. 3. Perempuan tidak wajib." },
{ q: "Sholat Jumat dikerjakan sebanyak...", options: ["tiga rakaat", "empat rakaat", "dua rakaat", "satu rakaat"], answer: 2, solution: "1. Sholat Jumat dua rakaat. 2. Dikerjakan berjamaah di masjid. 3. Diawali dengan dua khutbah." },
{ q: "Sebelum sholat Jumat, khatib menyampaikan khutbah sebanyak...", options: ["satu kali", "dua kali", "tiga kali", "empat kali"], answer: 1, solution: "1. Khutbah Jumat ada dua. 2. Disampaikan sebelum sholat. 3. Jamaah wajib mendengarkan." },
{ q: "Orang yang sholat Jumat tidak perlu lagi sholat...", options: ["Dzuhur", "Ashar", "Maghrib", "Subuh"], answer: 0, solution: "1. Sholat Jumat pengganti Dzuhur. 2. Waktunya sama dengan Dzuhur. 3. Yang tidak Jumat tetap wajib Dzuhur." },
{ q: "Sholat sunnah yang mengiringi sholat fardhu disebut...", options: ["rawatib", "dhuha", "tahajud", "witir"], answer: 0, solution: "1. Rawatib artinya pengiring. 2. Ada qabliyah sebelum fardhu. 3. Ada ba'diyah sesudah fardhu." },
{ q: "Sholat dhuha dikerjakan pada waktu...", options: ["tengah malam", "sore hari", "tengah hari", "pagi setelah matahari terbit"], answer: 3, solution: "1. Dhuha artinya waktu pagi. 2. Dikerjakan setelah matahari terbit. 3. Minimal dua rakaat." },
{ q: "Sholat tahajud dikerjakan pada...", options: ["malam hari setelah tidur", "pagi hari", "siang hari", "sore hari"], answer: 0, solution: "1. Tahajud sholat malam. 2. Dikerjakan setelah tidur malam. 3. Pahalanya sangat besar." },
{ q: "Sholat witir jumlah rakaatnya selalu...", options: ["ganjil", "genap", "dua", "empat"], answer: 0, solution: "1. Witir artinya ganjil. 2. Bisa satu, tiga, atau lima rakaat. 3. Dikerjakan sebagai penutup sholat malam." },
{ q: "Sholat Idul Fitri dikerjakan pada tanggal...", options: ["1 Ramadhan", "10 Dzulhijjah", "1 Syawal", "1 Muharram"], answer: 2, solution: "1. Idul Fitri artinya kembali suci. 2. Dikerjakan tanggal 1 Syawal. 3. Setelah sebulan berpuasa Ramadhan." },
{ q: "Sholat Idul Adha dikerjakan pada tanggal...", options: ["10 Dzulhijjah", "1 Syawal", "1 Ramadhan", "27 Rajab"], answer: 0, solution: "1. Idul Adha tanggal 10 Dzulhijjah. 2. Bertepatan dengan ibadah haji. 3. Setelah sholat disunnahkan berkurban." },
{ q: "Sholat jenazah dikerjakan dengan...", options: ["empat kali takbir", "ruku dan sujud", "tiga rakaat", "duduk tasyahud"], answer: 0, solution: "1. Sholat jenazah tanpa ruku dan sujud. 2. Hanya berdiri dan empat takbir. 3. Setiap takbir ada bacaannya." },
{ q: "Hukum sholat jenazah adalah...", options: ["fardhu kifayah", "fardhu ain", "sunnah", "wajib bagi semua"], answer: 0, solution: "1. Fardhu kifayah wajib kolektif. 2. Jika sudah ada yang sholat, gugur kewajiban. 3. Jika tidak ada, semua berdosa." },
{ q: "Sujud sahwi dilakukan ketika...", options: ["lupa dalam sholat", "lupa berwudhu", "lupa makan", "lupa belajar"], answer: 0, solution: "1. Sahwi artinya lupa. 2. Dilakukan jika lupa rakaat atau bacaan. 3. Dua kali sujud sebelum salam." },
{ q: "Sujud sahwi dikerjakan sebanyak...", options: ["satu kali", "tiga kali", "dua kali", "empat kali"], answer: 2, solution: "1. Sujud sahwi dua kali sujud. 2. Dikerjakan sebelum salam. 3. Untuk menutup kekurangan sholat." },
{ q: "Sujud tilawah dilakukan ketika...", options: ["mendengar atau membaca ayat sajdah", "selesai sholat", "lupa rakaat", "mendengar adzan"], answer: 0, solution: "1. Ayat sajdah ada tanda khusus. 2. Yang membaca atau mendengar sunnah sujud. 3. Hanya satu kali sujud." },
{ q: "Lafaz pertama dalam adzan adalah...", options: ["allahu akbar", "asyhadu alla ilaha illallah", "hayya alash shalah", "la ilaha illallah"], answer: 0, solution: "1. Adzan diawali takbir. 2. Allahu akbar dibaca dua kali. 3. Artinya Allah Mahabesar." },
{ q: "Orang yang mengumandangkan adzan disebut...", options: ["imam", "khatib", "bilal saja", "muadzin"], answer: 3, solution: "1. Muadzin tugasnya mengumandangkan adzan. 2. Muadzin pertama adalah Bilal. 3. Pahalanya besar." },
{ q: "Ketika mendengar adzan, kita disunnahkan...", options: ["menjawab adzan", "diam saja", "bernyanyi", "tidur"], answer: 0, solution: "1. Menjawab adzan itu sunnah. 2. Caranya menirukan lafaz muadzin. 3. Setelah itu baca doa setelah adzan." },
{ q: "Iqamah dikumandangkan...", options: ["setelah sholat", "sebelum sholat dimulai", "tengah malam", "saat khutbah"], answer: 1, solution: "1. Iqamah tanda sholat segera dimulai. 2. Lafaznya mirip adzan tapi lebih pendek. 3. Ada tambahan qad qaamatish shalah." },
{ q: "Rukun puasa ada dua, yaitu niat dan...", options: ["menahan diri dari yang membatalkan", "sahur", "berbuka", "tarawih"], answer: 0, solution: "1. Rukun puasa yang pertama niat. 2. Yang kedua menahan diri. 3. Dari terbit fajar sampai maghrib." },
{ q: "Makan sahur sebelum puasa hukumnya...", options: ["wajib", "haram", "sunnah", "makruh"], answer: 2, solution: "1. Sahur makan sebelum fajar. 2. Hukumnya sunnah. 3. Di dalam sahur ada berkah." },
{ q: "Menyegerakan berbuka puasa hukumnya...", options: ["sunnah", "wajib", "haram", "makruh"], answer: 0, solution: "1. Segera berbuka saat maghrib tiba. 2. Hukumnya sunnah. 3. Jangan menunda-nunda berbuka." },
{ q: "Zakat fitrah wajib dikeluarkan pada bulan...", options: ["Ramadhan", "Syawal", "Muharram", "Rajab"], answer: 0, solution: "1. Zakat fitrah membersihkan puasa. 2. Dikeluarkan selama bulan Ramadhan. 3. Paling lambat sebelum sholat Id." },
{ q: "Besar zakat fitrah untuk satu orang adalah...", options: ["setengah sha'", "dua sha'", "seperempat sha'", "satu sha'"], answer: 3, solution: "1. Satu sha' sekitar 2,5 sampai 3 kg. 2. Berupa makanan pokok seperti beras. 3. Diberikan kepada fakir miskin." },
{ q: "Wukuf adalah rukun haji yang dilakukan di...", options: ["Arafah", "Mina", "Muzdalifah", "Makkah"], answer: 0, solution: "1. Wukuf artinya berdiam diri. 2. Dilakukan di padang Arafah. 3. Pada tanggal 9 Dzulhijjah." },
{ q: "Thawaf adalah...", options: ["berlari antara Shafa dan Marwah", "melempar jumrah", "mengelilingi Ka'bah tujuh kali", "berdiam di Arafah"], answer: 2, solution: "1. Thawaf mengelilingi Ka'bah. 2. Sebanyak tujuh putaran. 3. Dimulai dari Hajar Aswad." },
{ q: "Sa'i adalah...", options: ["berlari kecil antara Shafa dan Marwah", "mengelilingi Ka'bah", "melempar jumrah", "wukuf di Arafah"], answer: 0, solution: "1. Sa'i dilakukan tujuh kali. 2. Antara bukit Shafa dan Marwah. 3. Mengenang Siti Hajar." },
{ q: "Melempar jumrah dilakukan di...", options: ["Arafah", "Mina", "Muzdalifah", "Makkah"], answer: 1, solution: "1. Jumrah ada tiga: ula, wustha, aqabah. 2. Dilakukan di Mina. 3. Dengan tujuh kerikil tiap jumrah." },
{ q: "Malaikat yang bertugas menyampaikan wahyu kepada para nabi adalah ...", options: ["Malaikat Jibril", "Malaikat Mikail", "Malaikat Israfil", "Malaikat Izrail"], answer: 0, solution: "1. Wahyu adalah pesan Allah untuk para nabi. 2. Malaikat Jibril yang menyampaikan wahyu. 3. Jadi jawabannya Malaikat Jibril." },
{ q: "Malaikat yang bertugas mengatur rezeki dan menurunkan hujan adalah ...", options: ["Malaikat Jibril", "Malaikat Mikail", "Malaikat Israfil", "Malaikat Malik"], answer: 1, solution: "1. Allah mengatur rezeki makhluk-Nya lewat malaikat. 2. Malaikat Mikail bertugas mengatur rezeki dan hujan. 3. Jadi jawabannya Malaikat Mikail." },
{ q: "Malaikat yang akan meniup sangkakala pada hari kiamat adalah ...", options: ["Malaikat Israfil", "Malaikat Jibril", "Malaikat Mikail", "Malaikat Raqib"], answer: 0, solution: "1. Sangkakala ditiup saat hari kiamat tiba. 2. Malaikat Israfil bertugas meniup sangkakala. 3. Jadi jawabannya Malaikat Israfil." },
{ q: "Malaikat yang bertugas mencabut nyawa makhluk adalah ...", options: ["Malaikat Malik", "Malaikat Ridwan", "Malaikat Izrail", "Malaikat Munkar"], answer: 2, solution: "1. Setiap yang bernyawa pasti akan mati. 2. Malaikat Izrail bertugas mencabut nyawa. 3. Jadi jawabannya Malaikat Izrail." },
{ q: "Dua malaikat yang akan menanyai manusia di alam kubur adalah ...", options: ["Malaikat Munkar dan Nakir", "Malaikat Raqib dan Atid", "Malaikat Jibril dan Mikail", "Malaikat Malik dan Ridwan"], answer: 0, solution: "1. Di alam kubur manusia akan ditanya tentang imannya. 2. Yang bertanya adalah Malaikat Munkar dan Nakir. 3. Jadi jawabannya Malaikat Munkar dan Nakir." },
{ q: "Dua malaikat yang bertugas mencatat amal baik dan amal buruk manusia adalah ...", options: ["Malaikat Jibril dan Israfil", "Malaikat Raqib dan Atid", "Malaikat Malik dan Ridwan", "Malaikat Munkar dan Nakir"], answer: 1, solution: "1. Semua amal manusia dicatat agar dihisab. 2. Malaikat Raqib dan Atid bertugas mencatat amal. 3. Jadi jawabannya Malaikat Raqib dan Atid." },
{ q: "Malaikat penjaga neraka bernama ...", options: ["Malaikat Ridwan", "Malaikat Malik", "Malaikat Jibril", "Malaikat Mikail"], answer: 1, solution: "1. Neraka dijaga agar penghuninya tidak keluar. 2. Malaikat Malik adalah penjaga neraka. 3. Jadi jawabannya Malaikat Malik." },
{ q: "Malaikat penjaga surga bernama ...", options: ["Malaikat Malik", "Malaikat Izrail", "Malaikat Israfil", "Malaikat Ridwan"], answer: 3, solution: "1. Surga dijaga oleh malaikat. 2. Malaikat Ridwan adalah penjaga surga. 3. Jadi jawabannya Malaikat Ridwan." },
{ q: "Jumlah malaikat yang wajib kita ketahui nama dan tugasnya adalah ...", options: ["Lima", "Delapan", "Sepuluh", "Dua belas"], answer: 2, solution: "1. Ada malaikat yang wajib kita ketahui nama dan tugasnya. 2. Jumlahnya ada sepuluh malaikat. 3. Jadi jawabannya sepuluh." },
{ q: "Rukun iman yang ketiga adalah beriman kepada ...", options: ["Allah", "Malaikat", "Kitab-kitab Allah", "Rasul-rasul Allah"], answer: 2, solution: "1. Rukun iman ada enam. 2. Urutan ketiga adalah iman kepada kitab-kitab Allah. 3. Jadi jawabannya kitab-kitab Allah." },
{ q: "Kitab suci yang diturunkan kepada Nabi Daud as adalah ...", options: ["Zabur", "Taurat", "Injil", "Al-Quran"], answer: 0, solution: "1. Setiap kitab diturunkan kepada nabi tertentu. 2. Kitab Zabur diturunkan kepada Nabi Daud. 3. Jadi jawabannya Zabur." },
{ q: "Kitab suci yang diturunkan kepada Nabi Isa as adalah ...", options: ["Taurat", "Zabur", "Injil", "Al-Quran"], answer: 2, solution: "1. Nabi Isa menerima kitab suci dari Allah. 2. Kitab itu bernama Injil. 3. Jadi jawabannya Injil." },
{ q: "Kitab suci terakhir yang diturunkan kepada Nabi Muhammad saw adalah ...", options: ["Zabur", "Injil", "Taurat", "Al-Quran"], answer: 3, solution: "1. Kitab suci terakhir diturunkan kepada Nabi Muhammad. 2. Kitab itu adalah Al-Quran. 3. Jadi jawabannya Al-Quran." },
{ q: "Kitab-kitab suci yang wajib diimani berjumlah ...", options: ["Dua", "Tiga", "Empat", "Enam"], answer: 2, solution: "1. Kitab suci yang wajib diimani adalah Taurat, Zabur, Injil, dan Al-Quran. 2. Jumlahnya ada empat. 3. Jadi jawabannya empat." },
{ q: "Contoh pengamalan iman kepada kitab-kitab Allah dalam sehari-hari adalah ...", options: ["Membaca dan mempelajari Al-Quran setiap hari", "Menyimpan Al-Quran di lemari tanpa dibaca", "Membaca Al-Quran hanya saat ujian", "Meminjam Al-Quran lalu tidak dikembalikan"], answer: 0, solution: "1. Iman kepada kitab harus dibuktikan dengan amal. 2. Caranya membaca dan mempelajari Al-Quran setiap hari. 3. Jadi itu contoh pengamalannya." },
{ q: "Makna beriman kepada kitab-kitab Allah adalah ...", options: ["Hanya menghafal nama-nama kitab", "Meyakini semua kitab dari Allah dan mengamalkan isi Al-Quran", "Meragukan isi Al-Quran", "Menganggap semua kitab isinya sama"], answer: 1, solution: "1. Beriman artinya percaya dengan sepenuh hati. 2. Kita percaya semua kitab dari Allah dan mengamalkan Al-Quran. 3. Itulah makna iman kepada kitab-kitab Allah." },
{ q: "Rukun iman yang keempat adalah beriman kepada ...", options: ["Kitab-kitab Allah", "Malaikat", "Rasul-rasul Allah", "Hari akhir"], answer: 2, solution: "1. Rukun iman ada enam. 2. Urutan keempat adalah iman kepada rasul-rasul Allah. 3. Jadi jawabannya rasul-rasul Allah." },
{ q: "Beriman kepada rasul-rasul Allah artinya ...", options: ["Meyakini rasul adalah utusan Allah yang benar", "Menganggap rasul manusia biasa tanpa wahyu", "Hanya menghafal nama-nama rasul", "Meragukan kerasulan mereka"], answer: 0, solution: "1. Rasul diutus Allah membawa wahyu. 2. Beriman artinya meyakini mereka benar-benar utusan Allah. 3. Jadi jawabannya meyakini rasul adalah utusan Allah yang benar." },
{ q: "Sifat wajib rasul yang artinya dapat dipercaya adalah ...", options: ["Amanah", "Khianat", "Lupa", "Malas"], answer: 0, solution: "1. Rasul punya sifat wajib yang mulia. 2. Amanah artinya dapat dipercaya. 3. Jadi jawabannya amanah." },
{ q: "Sifat wajib rasul yang artinya benar dan jujur adalah ...", options: ["Pandai berbohong", "Mudah lupa", "Menyembunyikan wahyu", "Shiddiq"], answer: 3, solution: "1. Shiddiq adalah sifat wajib rasul. 2. Shiddiq artinya benar dan jujur. 3. Jadi jawabannya shiddiq." },
{ q: "Contoh meneladani rasul dalam kehidupan sehari-hari adalah ...", options: ["Membohongi teman", "Berkata jujur dan tidak mencontek saat ulangan", "Mencontek saat ulangan", "Mencuri mainan teman"], answer: 1, solution: "1. Rasul adalah teladan terbaik. 2. Meneladaninya berarti berkata jujur dan tidak mencontek. 3. Jadi jawabannya berkata jujur dan tidak mencontek saat ulangan." },
{ q: "Sifat wajib rasul yang artinya menyampaikan wahyu Allah adalah ...", options: ["Tabligh", "Shiddiq", "Amanah", "Fathanah"], answer: 0, solution: "1. Rasul wajib menyampaikan wahyu Allah. 2. Sifat menyampaikan wahyu disebut tabligh. 3. Jadi jawabannya tabligh." },
{ q: "Hari akhir disebut juga yaumul hisab yang artinya ...", options: ["Hari perhitungan amal", "Hari kebangkitan", "Hari penimbangan amal", "Hari kiamat besar"], answer: 0, solution: "1. Hari akhir punya banyak nama. 2. Yaumul hisab artinya hari perhitungan amal. 3. Jadi jawabannya hari perhitungan amal." },
{ q: "Yaumul mizan artinya ...", options: ["Hari kebangkitan", "Hari perhitungan", "Hari penimbangan amal", "Hari pembalasan"], answer: 2, solution: "1. Amal baik dan buruk akan ditimbang. 2. Yaumul mizan artinya hari penimbangan amal. 3. Jadi jawabannya hari penimbangan amal." },
{ q: "Yaumul baats artinya ...", options: ["Hari perhitungan", "Hari kebangkitan dari kubur", "Hari penimbangan", "Hari pembalasan"], answer: 1, solution: "1. Manusia akan dibangkitkan dari kubur. 2. Yaumul baats artinya hari kebangkitan. 3. Jadi jawabannya hari kebangkitan dari kubur." },
{ q: "Salah satu tanda-tanda besar hari kiamat adalah ...", options: ["Matahari terbit dari barat", "Matahari terbit dari timur", "Hujan turun setiap hari", "Angin bertiup sepoi-sepoi"], answer: 0, solution: "1. Kiamat punya tanda-tanda besar. 2. Salah satunya matahari terbit dari barat. 3. Jadi jawabannya matahari terbit dari barat." },
{ q: "Contoh pengamalan iman kepada hari akhir adalah ...", options: ["Malas beribadah", "Berbuat jahat sesukanya", "Lupa kepada Allah", "Rajin beribadah dan berbuat baik"], answer: 3, solution: "1. Iman kepada hari akhir membuat kita waspada. 2. Kita jadi rajin beribadah dan berbuat baik. 3. Jadi itu contoh pengamalannya." },
{ q: "Ketika hari kiamat tiba, semua makhluk akan ...", options: ["Binasa dan hancur", "Hidup kekal di dunia", "Tidur selamanya", "Pindah ke planet lain"], answer: 0, solution: "1. Kiamat adalah hancurnya alam semesta. 2. Semua makhluk akan binasa kecuali Allah. 3. Jadi jawabannya binasa dan hancur." },
{ q: "Qadar artinya ...", options: ["Doa manusia", "Takdir yang ditetapkan Allah", "Usaha manusia", "Rezeki yang dicari"], answer: 1, solution: "1. Qadar adalah rukun iman keenam. 2. Qadar artinya takdir yang ditetapkan Allah. 3. Jadi jawabannya takdir yang ditetapkan Allah." },
{ q: "Contoh qadar atau takdir Allah adalah ...", options: ["Nilai ulangan", "Juara lomba lari", "Rezeki, jodoh, dan musibah", "Barang yang dibeli"], answer: 2, solution: "1. Ada hal yang sudah ditentukan Allah. 2. Contohnya rezeki, jodoh, dan musibah. 3. Jadi jawabannya rezeki, jodoh, dan musibah." },
{ q: "Setelah berusaha dengan sungguh-sungguh, seorang muslim harus ...", options: ["Tawakal", "Putus asa", "Menyerah sebelum berusaha", "Menyalahkan orang lain"], answer: 0, solution: "1. Setelah berusaha kita serahkan hasilnya. 2. Berserah diri kepada Allah disebut tawakal. 3. Jadi jawabannya tawakal." },
{ q: "Ikhtiar artinya ...", options: ["Berdiam diri saja", "Menunggu keajaiban", "Meminta-minta", "Berusaha dengan sungguh-sungguh"], answer: 3, solution: "1. Allah menyuruh manusia berusaha. 2. Berusaha sungguh-sungguh disebut ikhtiar. 3. Jadi jawabannya berusaha dengan sungguh-sungguh." },
{ q: "Ketika mendapat musibah, sikap muslim yang beriman kepada qada dan qadar adalah ...", options: ["Marah dan menyalahkan Allah", "Sabar dan ikhlas", "Putus asa", "Dendam kepada orang"], answer: 1, solution: "1. Musibah adalah ujian dari Allah. 2. Sikap yang benar adalah sabar dan ikhlas. 3. Jadi jawabannya sabar dan ikhlas." },
{ q: "Orang yang beriman kepada qada dan qadar tetap rajin berusaha karena ...", options: ["Usaha adalah kewajiban manusia", "Hasil pasti datang tanpa usaha", "Pasrah tanpa berusaha", "Takdir bisa diubah seenaknya"], answer: 0, solution: "1. Takdir Allah tidak menghapus kewajiban berusaha. 2. Manusia wajib berusaha, Allah yang menentukan hasil. 3. Jadi orang beriman tetap rajin berusaha." },
{ q: "Jumlah seluruh surat dalam Al-Quran adalah ...", options: ["110", "112", "114", "116"], answer: 2, solution: "1. Al-Quran terdiri dari banyak surat. 2. Jumlah seluruhnya 114 surat. 3. Jadi jawabannya 114." },
{ q: "Al-Quran terdiri atas ... juz.", options: ["20", "30", "40", "50"], answer: 1, solution: "1. Al-Quran dibagi menjadi beberapa juz agar mudah dibaca. 2. Jumlahnya 30 juz. 3. Jadi jawabannya 30." },
{ q: "Al-Quran diturunkan dalam bahasa ...", options: ["Arab", "Indonesia", "Inggris", "Ibrani"], answer: 0, solution: "1. Al-Quran diturunkan dalam satu bahasa. 2. Bahasa itu adalah bahasa Arab. 3. Jadi jawabannya Arab." },
{ q: "Al-Quran diturunkan oleh Allah secara ...", options: ["Sekaligus", "Bertahap sedikit demi sedikit", "Acak tanpa aturan", "Tertunda lama"], answer: 1, solution: "1. Al-Quran tidak turun sekaligus. 2. Al-Quran turun bertahap selama kurang lebih 23 tahun. 3. Jadi jawabannya bertahap sedikit demi sedikit." },
{ q: "Nabi Nuh as diperintah Allah membuat kapal besar karena akan datang ...", options: ["Banjir besar", "Gempa bumi", "Gunung meletus", "Badai pasir"], answer: 0, solution: "1. Kaum Nabi Nuh tidak mau beriman. 2. Allah akan menurunkan banjir besar. 3. Nabi Nuh diperintah membuat kapal agar selamat." },
{ q: "Nabi Hud as diutus Allah kepada kaum ...", options: ["Ad", "Tsamud", "Madyan", "Saba"], answer: 0, solution: "1. Nabi Hud diutus kepada satu kaum yang sombong. 2. Kaum itu bernama kaum Ad. 3. Jadi jawabannya kaum Ad." },
{ q: "Mukjizat Nabi Shaleh as adalah ...", options: ["Tongkat menjadi ular", "Membelah bulan", "Unta betina keluar dari batu", "Menyembuhkan orang buta"], answer: 2, solution: "1. Kaum Tsamud meminta bukti kenabian. 2. Allah mengeluarkan unta betina dari batu. 3. Jadi jawabannya unta betina keluar dari batu." },
{ q: "Kaum Nabi Luth as suka berbuat keji, akhirnya negeri mereka ...", options: ["Tenggelam oleh banjir", "Dibalikkan oleh Allah hingga hancur", "Berubah menjadi padang pasir", "Tertimbun salju"], answer: 1, solution: "1. Kaum Nabi Luth menolak ajakannya. 2. Allah membalikkan negeri mereka hingga hancur. 3. Jadi jawabannya dibalikkan oleh Allah hingga hancur." },
{ q: "Nabi Ismail as hampir disembelih ayahnya, lalu Allah menggantinya dengan ...", options: ["Seekor kambing", "Seekor unta", "Seekor sapi", "Seekor ayam"], answer: 0, solution: "1. Ini adalah ujian keimanan Nabi Ibrahim dan Ismail. 2. Allah mengganti Ismail dengan seekor kambing. 3. Dari sinilah asal ibadah kurban." },
{ q: "Nabi Yusuf as bermimpi melihat ...", options: ["Terbang ke langit", "Jatuh ke bumi", "Berbicara dengannya", "Sebelas bintang, matahari, dan bulan bersujud kepadanya"], answer: 3, solution: "1. Nabi Yusuf bermimpi aneh saat kecil. 2. Ia melihat sebelas bintang, matahari, dan bulan bersujud kepadanya. 3. Mimpi itu tanda ia akan menjadi orang mulia." },
{ q: "Nabi Ayub as terkenal sangat sabar ketika ...", options: ["Kehilangan kapalnya", "Ditimpa penyakit yang lama", "Dikejar raja zalim", "Dibuang ke dalam sumur"], answer: 1, solution: "1. Nabi Ayub diuji Allah dengan berat. 2. Ia ditimpa penyakit yang lama tetapi tetap sabar. 3. Jadi jawabannya ditimpa penyakit yang lama." },
{ q: "Kitab suci yang diterima Nabi Daud as adalah ...", options: ["Zabur", "Taurat", "Injil", "Al-Quran"], answer: 0, solution: "1. Nabi Daud menerima kitab suci. 2. Kitab itu bernama Zabur. 3. Jadi jawabannya Zabur." },
{ q: "Mukjizat Nabi Daud as adalah ...", options: ["Tongkatnya menjadi ular", "Ia bisa terbang", "Besi menjadi lunak di tangannya dan suaranya merdu", "Ia bisa menghidupkan orang mati"], answer: 2, solution: "1. Allah memberi kelebihan kepada Nabi Daud. 2. Besi menjadi lunak di tangannya dan suaranya merdu saat membaca Zabur. 3. Jadi itulah mukjizatnya." },
{ q: "Nabi Sulaiman as diberi kelebihan dapat memahami ...", options: ["Isi hati manusia", "Pembicaraan semut dan burung", "Bahasa tumbuhan", "Suara angin"], answer: 1, solution: "1. Nabi Sulaiman adalah raja yang bijak. 2. Ia dapat memahami pembicaraan semut dan burung. 3. Jadi jawabannya pembicaraan semut dan burung." },
{ q: "Mukjizat Nabi Isa as adalah dapat berbicara ketika masih ...", options: ["Bayi dalam buaian", "Anak remaja", "Orang dewasa", "Orang tua"], answer: 0, solution: "1. Orang menuduh ibunda Isa berbuat dosa. 2. Bayi Isa berbicara dalam buaian membela ibunya. 3. Jadi jawabannya bayi dalam buaian." },
{ q: "Nabi Muhammad saw lahir pada 12 Rabiul Awal pada tahun ...", options: ["Tahun Gajah", "Tahun Hijrah", "Tahun Kurban", "Tahun Badar"], answer: 0, solution: "1. Tahun kelahiran Nabi punya nama khusus. 2. Disebut tahun Gajah karena ada pasukan bergajah. 3. Jadi jawabannya tahun Gajah." },
{ q: "Ayah Nabi Muhammad saw bernama ...", options: ["Abdul Muthalib", "Abu Thalib", "Abdullah", "Hamzah"], answer: 2, solution: "1. Ayah Nabi wafat sebelum beliau lahir. 2. Nama ayah beliau adalah Abdullah. 3. Jadi jawabannya Abdullah." },
{ q: "Ibu Nabi Muhammad saw bernama ...", options: ["Khadijah", "Aminah", "Fatimah", "Aisyah"], answer: 1, solution: "1. Ibu Nabi wafat saat beliau masih kecil. 2. Nama ibu beliau adalah Aminah. 3. Jadi jawabannya Aminah." },
{ q: "Istri pertama Nabi Muhammad saw bernama ...", options: ["Khadijah", "Aisyah", "Fatimah", "Hafsah"], answer: 0, solution: "1. Istri pertama Nabi selalu mendukung dakwahnya. 2. Beliau bernama Khadijah. 3. Jadi jawabannya Khadijah." },
{ q: "Wahyu pertama yang diterima Nabi di Gua Hira diawali dengan kata ...", options: ["Qul", "Yasin", "Alam", "Iqra"], answer: 3, solution: "1. Nabi menerima wahyu pertama di Gua Hira. 2. Wahyu itu surat Al-Alaq yang diawali kata Iqra. 3. Iqra artinya bacalah." },
{ q: "Nabi Muhammad saw dijuluki Al-Amin yang artinya ...", options: ["Pemberani", "Dapat dipercaya", "Dermawan", "Penyabar"], answer: 1, solution: "1. Sejak muda Nabi terkenal jujur. 2. Al-Amin artinya dapat dipercaya. 3. Jadi jawabannya dapat dipercaya." },
{ q: "Nabi Muhammad saw hijrah dari Makkah ke kota ...", options: ["Thaif", "Yaman", "Madinah", "Syam"], answer: 2, solution: "1. Kaum kafir Makkah memusuhi Nabi. 2. Nabi hijrah ke kota Madinah. 3. Jadi jawabannya Madinah." },
{ q: "Sahabat yang menemani Nabi Muhammad saw berhijrah ke Madinah adalah ...", options: ["Abu Bakar", "Umar bin Khattab", "Utsman bin Affan", "Ali bin Abi Thalib"], answer: 0, solution: "1. Nabi hijrah diam-diam pada malam hari. 2. Yang menemaninya adalah Abu Bakar. 3. Jadi jawabannya Abu Bakar." },
{ q: "Khalifah kedua setelah Abu Bakar adalah ...", options: ["Utsman bin Affan", "Umar bin Khattab", "Ali bin Abi Thalib", "Thalhah bin Ubaidillah"], answer: 1, solution: "1. Abu Bakar adalah khalifah pertama. 2. Penggantinya adalah Umar bin Khattab. 3. Jadi jawabannya Umar bin Khattab." },
{ q: "Sahabat yang berjasa membukukan Al-Quran menjadi satu mushaf adalah ...", options: ["Utsman bin Affan", "Ali bin Abi Thalib", "Umar bin Khattab", "Abu Bakar"], answer: 0, solution: "1. Al-Quran perlu dibukukan agar tidak hilang. 2. Utsman bin Affan membukukannya menjadi satu mushaf. 3. Jadi jawabannya Utsman bin Affan." },
{ q: "Khalifah keempat yang juga sepupu dan menantu Nabi saw adalah ...", options: ["Utsman bin Affan", "Umar bin Khattab", "Zubair bin Awwam", "Ali bin Abi Thalib"], answer: 3, solution: "1. Ali adalah sepupu Nabi yang masuk Islam sejak kecil. 2. Ia menjadi khalifah keempat. 3. Jadi jawabannya Ali bin Abi Thalib." },
{ q: "Asmaul Husna Al-Malik artinya ...", options: ["Maha Raja", "Maha Suci", "Maha Pemberi", "Maha Mendengar"], answer: 0, solution: "1. Al-Malik adalah salah satu nama Allah. 2. Artinya Maha Raja. 3. Jadi jawabannya Maha Raja." },
{ q: "Asmaul Husna Al-Quddus artinya ...", options: ["Maha Raja", "Maha Suci", "Maha Kuat", "Maha Hidup"], answer: 1, solution: "1. Al-Quddus adalah nama Allah. 2. Artinya Maha Suci dari segala kekurangan. 3. Jadi jawabannya Maha Suci." },
{ q: "Asmaul Husna As-Salam artinya ...", options: ["Maha Pengampun", "Maha Mengetahui", "Maha Pemberi Keselamatan", "Maha Adil"], answer: 2, solution: "1. As-Salam adalah nama Allah. 2. Artinya Maha Pemberi Keselamatan. 3. Jadi jawabannya Maha Pemberi Keselamatan." },
{ q: "Asmaul Husna Al-Ghaffar artinya ...", options: ["Maha Pengampun", "Maha Penyayang", "Maha Kaya", "Maha Bijaksana"], answer: 0, solution: "1. Manusia sering berbuat dosa. 2. Al-Ghaffar artinya Maha Pengampun. 3. Jadi jawabannya Maha Pengampun." },
{ q: "Asmaul Husna As-Sami artinya ...", options: ["Maha Melihat", "Maha Mengetahui", "Maha Kuasa", "Maha Mendengar"], answer: 3, solution: "1. Allah mendengar semua doa hamba-Nya. 2. As-Sami artinya Maha Mendengar. 3. Jadi jawabannya Maha Mendengar." },
{ q: "Asmaul Husna Al-Bashir artinya ...", options: ["Maha Mendengar", "Maha Melihat", "Maha Mengetahui", "Maha Lembut"], answer: 1, solution: "1. Tidak ada yang tersembunyi dari Allah. 2. Al-Bashir artinya Maha Melihat. 3. Jadi jawabannya Maha Melihat." },
{ q: "Asmaul Husna Al-Alim artinya ...", options: ["Maha Mengetahui", "Maha Melihat", "Maha Mendengar", "Maha Adil"], answer: 0, solution: "1. Allah tahu segala sesuatu. 2. Al-Alim artinya Maha Mengetahui. 3. Jadi jawabannya Maha Mengetahui." },
{ q: "Surat Al-Kautsar terdiri atas ... ayat.", options: ["3", "4", "5", "7"], answer: 0, solution: "1. Al-Kautsar adalah surat pendek. 2. Jumlah ayatnya 3 ayat. 3. Jadi jawabannya 3." },
{ q: "Surat Al-Fil menceritakan tentang ...", options: ["Banjir besar zaman Nabi Nuh", "Pasukan bergajah yang hendak menghancurkan Kakbah", "Kisah Nabi Yusuf", "Turunnya hujan lebat"], answer: 1, solution: "1. Al-Fil artinya gajah. 2. Surat ini tentang pasukan bergajah yang hendak menghancurkan Kakbah. 3. Allah menghancurkan mereka dengan burung ababil." },
{ q: "Surat Al-Maun menjelaskan ciri orang yang mendustakan agama, yaitu ...", options: ["Menghardik anak yatim dan enggan menolong", "Rajin sholat malam", "Suka bersedekah", "Hormat kepada guru"], answer: 0, solution: "1. Ada orang yang mengaku beragama tetapi jahat. 2. Cirinya menghardik anak yatim dan enggan menolong. 3. Jadi jawabannya menghardik anak yatim dan enggan menolong." },
{ q: "Surat Al-Ashr mengajarkan manusia akan merugi kecuali ...", options: ["Kaya raya", "Terkenal", "Beriman dan beramal saleh", "Pandai berdagang"], answer: 2, solution: "1. Al-Ashr artinya demi masa. 2. Manusia merugi kecuali yang beriman dan beramal saleh. 3. Jadi jawabannya beriman dan beramal saleh." },
{ q: "Surat Al-Qadr menjelaskan malam Lailatul Qadar lebih baik daripada ...", options: ["Seribu bulan", "Seratus malam", "Sepuluh bulan", "Satu tahun"], answer: 0, solution: "1. Lailatul Qadar adalah malam yang mulia. 2. Nilainya lebih baik dari seribu bulan. 3. Jadi jawabannya seribu bulan." },
{ q: "Surat Adh-Dhuha menghibur Nabi bahwa Allah ...", options: ["Marah kepadanya", "Melupakannya", "Menghukumnya", "Tidak meninggalkannya"], answer: 3, solution: "1. Nabi sempat sedih karena wahyu terhenti. 2. Allah menegaskan tidak meninggalkannya. 3. Jadi jawabannya tidak meninggalkannya." },
{ q: "Doa bangun tidur diawali dengan bacaan ...", options: ["Alhamdulillah", "Bismillah", "Subhanallah", "Astaghfirullah"], answer: 0, solution: "1. Bangun tidur adalah nikmat Allah. 2. Kita memuji Allah dengan Alhamdulillah. 3. Jadi doa bangun tidur diawali Alhamdulillah." },
{ q: "Saat masuk rumah, kita disunnahkan ...", options: ["Berteriak memanggil", "Mengucapkan salam", "Langsung masuk diam-diam", "Mengetuk keras-keras"], answer: 1, solution: "1. Rumah harus dimasuki dengan adab. 2. Kita disunnahkan mengucapkan salam. 3. Jadi jawabannya mengucapkan salam." },
{ q: "Doa yang dibaca saat keluar rumah adalah ...", options: ["Bismillahi tawakkaltu alallah", "Alhamdulillah", "Subhanallah", "Allahu Akbar"], answer: 0, solution: "1. Keluar rumah kita mohon perlindungan Allah. 2. Doanya Bismillahi tawakkaltu alallah. 3. Artinya dengan nama Allah aku bertawakal." },
{ q: "Doa naik kendaraan diawali dengan bacaan ...", options: ["Alhamdulillahilladzi athamana", "Allahumma inni asaluka", "Subhanalladzi sakhkhara lana hadza", "Bismillah saja"], answer: 2, solution: "1. Naik kendaraan kita bersyukur kepada Allah. 2. Doanya diawali Subhanalladzi sakhkhara lana hadza. 3. Jadi jawabannya bacaan itu." },
{ q: "Doa sebelum belajar berbunyi ...", options: ["Allahumma inni asaluka", "Robbi zidni ilma warzuqni fahma", "Alhamdulillah", "Subhanallah"], answer: 1, solution: "1. Sebelum belajar kita berdoa mohon ilmu. 2. Doanya Robbi zidni ilma warzuqni fahma. 3. Artinya ya Tuhanku tambahkan ilmuku." },
{ q: "Doa ketika turun hujan adalah ...", options: ["Allahumma shayyiban nafian", "Allahumma inni asaluka", "Robbana atina", "Alhamdulillah"], answer: 0, solution: "1. Hujan adalah rahmat Allah. 2. Doanya Allahumma shayyiban nafian. 3. Artinya ya Allah jadikan hujan yang bermanfaat." },
{ q: "Andi dititipi uang kas kelas. Sikap amanah yang harus dilakukan Andi adalah ...", options: ["Menjaga uang itu dan tidak memakainya", "Memakai sedikit untuk jajan", "Meminjamkan ke teman", "Menyembunyikannya"], answer: 0, solution: "1. Amanah artinya menjaga titipan. 2. Andi harus menjaga uang itu dan tidak memakainya. 3. Jadi jawabannya menjaga uang itu." },
{ q: "Sabar artinya ...", options: ["Marah-marah saat susah", "Menangis terus-menerus", "Menyerah begitu saja", "Tabah menghadapi kesulitan tanpa mengeluh"], answer: 3, solution: "1. Hidup kadang penuh ujian. 2. Sabar artinya tabah menghadapi kesulitan tanpa mengeluh. 3. Jadi jawabannya tabah menghadapi kesulitan." },
{ q: "Contoh perilaku syukur atas nikmat Allah adalah ...", options: ["Menyombongkan nikmat", "Menggunakan nikmat untuk kebaikan", "Menyia-nyiakan nikmat", "Mengeluh terus-menerus"], answer: 1, solution: "1. Syukur artinya berterima kasih kepada Allah. 2. Caranya menggunakan nikmat untuk kebaikan. 3. Jadi jawabannya menggunakan nikmat untuk kebaikan." },
{ q: "Sikap pemaaf artinya ...", options: ["Memaafkan kesalahan orang lain", "Membalas dendam", "Menyimpan dendam", "Memusuhi terus"], answer: 0, solution: "1. Setiap orang bisa berbuat salah. 2. Pemaaf artinya memaafkan kesalahan orang lain. 3. Jadi jawabannya memaafkan kesalahan orang lain." },
{ q: "Riya adalah beribadah atau berbuat baik agar ...", options: ["Diridhai Allah", "Masuk surga", "Dipuji orang lain", "Disayang orang tua"], answer: 2, solution: "1. Riya adalah akhlak tercela. 2. Riya artinya berbuat baik agar dipuji orang. 3. Amal yang riya tidak berpahala." },
{ q: "Contoh menghormati guru adalah ...", options: ["Mendengarkan penjelasan guru dengan baik", "Berbicara saat guru menjelaskan", "Mengejek guru", "Tidak mengerjakan tugas"], answer: 0, solution: "1. Guru berjasa mengajarkan ilmu. 2. Kita menghormatinya dengan mendengarkan penjelasan. 3. Jadi jawabannya mendengarkan penjelasan guru dengan baik." },
{ q: "Hari Raya Idul Fitri dirayakan setiap tanggal ...", options: ["1 Syawal", "1 Ramadhan", "10 Dzulhijjah", "1 Muharram"], answer: 0, solution: "1. Idul Fitri datang setelah puasa Ramadhan. 2. Dirayakan pada 1 Syawal. 3. Jadi jawabannya 1 Syawal." },
{ q: "Pada Hari Raya Idul Adha, umat Islam disunnahkan ...", options: ["Berpuasa penuh sebulan", "Menyembelih hewan kurban", "Begadang semalaman", "Berburu hewan"], answer: 1, solution: "1. Idul Adha disebut juga Hari Raya Kurban. 2. Umat Islam menyembelih hewan kurban. 3. Jadi jawabannya menyembelih hewan kurban." },
{ q: "Peristiwa Isra Miraj berkaitan dengan perintah ...", options: ["Puasa Ramadhan", "Zakat", "Haji", "Sholat lima waktu"], answer: 3, solution: "1. Nabi diperjalankan pada malam hari. 2. Beliau menerima perintah sholat lima waktu. 3. Jadi jawabannya sholat lima waktu." },
{ q: "Bulan pertama dalam kalender Hijriyah adalah ...", options: ["Muharram", "Ramadhan", "Syawal", "Dzulhijjah"], answer: 0, solution: "1. Kalender Hijriyah punya 12 bulan. 2. Bulan pertamanya adalah Muharram. 3. Jadi jawabannya Muharram." },
{ q: "Umat Islam berpuasa wajib pada bulan ...", options: ["Muharram", "Syawal", "Ramadhan", "Dzulqadah"], answer: 2, solution: "1. Puasa wajib dilakukan setahun sekali. 2. Bulannya adalah Ramadhan. 3. Jadi jawabannya Ramadhan." },
{ q: "Bulan yang datang setelah Syaban adalah ...", options: ["Syawal", "Ramadhan", "Rajab", "Rabiul Awal"], answer: 1, solution: "1. Urutan bulan Hijriyah: Rajab, Syaban, lalu Ramadhan. 2. Setelah Syaban adalah Ramadhan. 3. Jadi jawabannya Ramadhan." },
{ q: "Minuman keras (khamr) hukumnya ...", options: ["Haram", "Halal", "Makruh", "Mubah"], answer: 0, solution: "1. Khamr memabukkan dan merusak akal. 2. Allah mengharamkan khamr. 3. Jadi hukumnya haram." },
{ q: "Memakan bangkai hewan hukumnya ...", options: ["Haram", "Halal", "Makruh", "Wajib"], answer: 0, solution: "1. Hewan harus disembelih sesuai syariat. 2. Bangkai haram dimakan. 3. Jadi jawabannya haram." },
{ q: "Bersedekah kepada orang yang membutuhkan hukumnya ...", options: ["Sunnah dan berpahala", "Wajib", "Haram", "Makruh"], answer: 0, solution: "1. Sedekah adalah memberi dengan ikhlas. 2. Hukumnya sunnah dan berpahala. 3. Jadi jawabannya sunnah dan berpahala." },
{ q: "Menuntut ilmu bagi setiap muslim hukumnya ...", options: ["Sunnah", "Wajib", "Haram", "Makruh"], answer: 1, solution: "1. Nabi memerintahkan umatnya menuntut ilmu. 2. Hukumnya wajib bagi setiap muslim. 3. Jadi jawabannya wajib." },
  ]
};
